      ' What if the record screen looks attractive but users cannot understand the numbers?',
    '시각적 완성도만으로 좋은 UX가 되지 않습니다. 용어, 비교 기준, 결과의 의미를 설명하고 사용자가 그 설명을 제대로 이해하는지 평가해야 합니다. 특히 측정 사실과 AI의 추정을 구분해야 합니다.':
      ' Visual polish alone does not create good UX. Explain terms, comparison criteria, and the meaning of results, then evaluate whether users understand those explanations. In particular, distinguish measured facts from AI estimates.',
    'AI의 분류 정확도가 높으면 HCI 평가를 생략해도 될까?':
      ' Can HCI evaluation be skipped if AI classification accuracy is high?',
    '생략할 수 없습니다. 사용자가 데이터를 잘못 입력하거나 결과를 오해하면 좋은 성능이 좋은 경험으로 이어지지 않습니다. 결과의 이해, 오류 복구, 실제 환경과 접근성도 평가해야 합니다.':
      ' No. If users enter data incorrectly or misunderstand results, good performance does not lead to a good experience. Evaluate understanding, error recovery, actual environments, and accessibility as well.',
