      ' DBM concerns identifying conditions, while DTx concerns evidence-based therapeutic interventions',
    '사용자가 목적에 필요한 기능을 찾고 효율적으로 조작할 수 있는지는 사용성의 문제입니다. 기능의 존재 자체와 구분해야 합니다.':
      ' Whether users can find and efficiently operate the functions needed for a goal is a usability issue. This differs from the mere existence of a function.',
