    '웨어러블은 몸에 착용하는 기기, 센서는 움직임·온도 등 물리적 신호를 감지하는 장치입니다.':
      ' A wearable is worn on the body; a sensor detects physical signals such as movement or temperature.',
    '광용적맥파 · PPG': ' Photoplethysmography · PPG',
