    '네 단계와 하위 요소를 순서대로 말하면?':
      ' What are the four stages and their components in order?',
    '분석(관계자·과업·맥락) → 기획(콘셉트 모형·비즈니스 모델) → 설계(아키텍처·인터랙션·인터페이스) → 평가(유용성·사용성·신뢰성). 문제 발견 시 이전 단계로 돌아가 개선.':
      ' Analysis (stakeholders, tasks, context) → Planning (concept model, business model) → Design (architecture, interaction, interface) → Evaluation (usefulness, usability, reliability). Return to earlier stages and improve when problems are found.',
    'ESG는 무엇이며 왜 HCI에서 중요한가?': ' What is ESG, and why does it matter in HCI?',
