    '감각적 경험 · 무엇이 실제처럼 느껴지는가?': ' Sensory experience · What feels real?',
    '말풍선과 알림음은 감각 자극입니다. 상대의 입력 상태가 바로 보이면 함께 대화한다는 사회적 실재감을 느낄 수 있습니다. 자극을 늘리는 것이 언제나 좋은 경험을 뜻하지는 않습니다.':
      ' Message bubbles and notification sounds are sensory stimuli. Seeing the other person’s typing status immediately can create social presence, a feeling of conversing together. More stimulation does not always mean a better experience.',
    '실재감(Presence)': ' Presence',
    '은 어떤 대상이나 환경이 실제로 존재하는 것처럼 느끼는 감각입니다. ‘화면을 본다’에서 ‘그곳에 있는 듯하다’로 경험이 달라지는 지점을 설명합니다.':
      ' is the feeling that an object or environment really exists. It describes the shift from “looking at a screen” to “feeling as if you are there.”',
    '물리적 실재감': ' Physical presence',
    '사물이나 대상이 실제로 눈앞에 있는 듯한 느낌입니다. 원본 예: AR로 내 방에 가상 가구를 배치하는 경험.':
      ' The feeling that an object is actually in front of you. Source example: placing virtual furniture in your room using AR.',
    '사회적 실재감': ' Social presence',
    '다른 사람이 실제로 함께 있는 듯한 느낌입니다. 원본 예: 가상 회의에서 상대의 시선과 몸짓을 느끼는 경험.':
      ' The feeling that another person is actually there with you. Source example: experiencing another person’s gaze and gestures in a virtual meeting.',
    '자아 실재감': ' Self-presence',
    '디지털 공간에 나 자신이 존재하는 듯한 느낌입니다. 원본 예: VR 속 손이 내 손 움직임을 따라오는 경험.':
      ' The feeling that you yourself exist in a digital space. Source example: virtual hands following your hand movements in VR.',
    '생동감과 상호성을 구분하기': ' Distinguish vividness from interactivity',
