    '경험적·쾌락적 가치:': ' Experiential or hedonic value: ',
    '과정의 재미·즐거움.': ' Fun and enjoyment in the process.',
    '수단적 가치:': ' Instrumental value: ',
    '다른 목표를 달성하는 데의 효용.': ' Usefulness in achieving another goal.',
