      ' Verify through concrete principles such as usefulness, usability, and reliability, and through evaluation',
    '현재 → 욕구 → 환경 → 목표': ' Current state → Needs → Environment → Goal',
    '온라인 학습에서의 분석 · 이해 보완':
      ' Analysis of online learning · Supplementary explanation',
    '현재 경험': ' Current experience',
    '동영상은 보지만 질문과 피드백이 늦습니다. 진도는 정해져 있고 동료와 연결될 기회가 적습니다.':
      ' Students watch videos but questions and feedback are delayed. Progress is fixed and opportunities to connect with peers are limited.',
    '내적 갈등': ' Internal conflict',
    '학생은 즉각적 피드백과 자기 속도에 맞는 학습을 원합니다. 필요한 때 다른 학생과 의견을 나누고 싶어 합니다.':
      ' Students want immediate feedback and learning at their own pace. They want to exchange ideas with others when needed.',
    '외부 환경': ' External environment',
    '생활방식의 변화(S), 구독료 부담(E), AI 피드백 기술의 가능성과 한계(T)를 조사합니다.':
      ' Investigate lifestyle changes (S), subscription costs (E), and the possibilities and limitations of AI feedback (T).',
    '목표 경험': ' Target experience',
    '자신의 속도로 배우고 필요한 피드백과 동료의 도움을 받을 수 있는 경험을 제공합니다.':
      ' Provide an experience of learning at one’s own pace with needed feedback and peer support.',
    '구현할 수 있는 선택': ' Possible implementation choices',
    '문항별 피드백, 난이도 선택, 선택형 스터디 기능을 검토할 수 있습니다. 목표와 무관한 기능을 무조건 늘릴 필요는 없습니다.':
      ' Consider question-specific feedback, difficulty selection, and optional study groups. There is no need to add functions unrelated to the goal.',
    '평가할 질문': ' Evaluation questions',
    '학생이 피드백을 이해하는가? 학습 속도를 실제로 조절할 수 있는가? 원할 때 연결되고 원하지 않을 때 알림을 줄일 수 있는가?':
      ' Do students understand the feedback? Can they actually adjust the learning pace? Can they connect when they want and reduce notifications when they do not?',
    '서술형 답안의 순서:': ' Suggested order for a written answer: ',
    '정의 → 조절 요인 → 사례 → 적절한 수준을 선택한 이유. 이 순서는 학습용 답안 구성법이며 교수님의 채점 기준을 뜻하지 않습니다.':
      ' Definition → Regulating factors → Example → Reason for the chosen level. This is a study aid for organizing answers, not the instructor’s grading criteria.',
    '정답: 사용자·과업·환경에 맞는 수준이 필요합니다. 원본 p. 16은 실재감의 무조건적인 극대화를 목표로 삼지 않습니다.':
      ' Answer: the level should suit users, tasks, and environments. Source p. 16 does not set unconditional maximization of presence as the goal.',
    '1. 실재감이 높으면 언제나 좋은 UX인가요?':
      ' 1. Does higher presence always produce better UX?',
    '그렇다. 실재감은 높을수록 좋다.': ' Yes. More presence is always better.',
    '아니다. 사용자·과업·환경에 맞는 수준이 필요하다.':
      ' No. The level should suit users, tasks, and environments.',
    '아니다. 실재감은 UX와 무관하다.': ' No. Presence is unrelated to UX.',
    '정답: 생동감의 넓이입니다. 넓이는 감각 채널의 수이며, 깊이는 한 채널에서 제공되는 자극의 수준입니다.':
      ' Answer: vividness breadth. Breadth is the number of sensory channels, while depth is the level of stimulation within one channel.',
    '2. 시각에 청각·촉각 채널을 추가했다면?':
      ' 2. What changes when auditory and tactile channels are added to vision?',
    '생동감의 넓이가 달라진다.': ' Vividness breadth changes.',
    '기인점이 반드시 외재적으로 바뀐다.': ' The locus of causality necessarily becomes extrinsic.',
    '관계의 밀도가 반드시 높아진다.': ' Relationship density necessarily increases.',
    '정답: 목적 요인과 절차 요인입니다. 각각 경험의 가치와 사용자·시스템의 주도성을 살펴봅니다.':
      ' Answer: purpose and procedure factors. They examine experiential value and user or system initiative, respectively.',
    '3. 기인점을 조절하는 두 요인은?': ' 3. Which two factors regulate locus of causality?',
    '밀도와 강도': ' Density and strength',
    '목적과 절차': ' Purpose and procedure',
    '속도와 해상도': ' Speed and resolution',
    '정답: 관계의 강도가 높을 수 있습니다. 강도는 상호작용의 빈도·기간·정보량과 관련되며, 인원수만으로 정하지 않습니다.':
      ' Answer: relationship strength may be high. Strength concerns the frequency, duration, and information exchanged in interaction, not headcount alone.',
    '4. 두 사람이 매일 깊이 있는 피드백을 주고받으면?':
      ' 4. What if two people exchange in-depth feedback every day?',
    '인원이 적으므로 관계의 강도가 반드시 낮다.':
      ' Relationship strength must be low because there are few people.',
    '생동감만 달라진다.': ' Only vividness changes.',
    '관계의 강도가 높을 수 있다.': ' Relationship strength may be high.',
    '정답: 원본 pp. 47–49에서 X는 구성적 경험의 복잡도, Y는 감각적 경험의 실재감, Z는 판단적 경험의 기인점입니다.':
      ' Answer: on source pp. 47–49, X is compositional complexity, Y is sensory presence, and Z is judgmental locus of causality.',
    '5. 3차원 모형의 축 대응으로 맞는 것은?':
      ' 5. Which axis mapping matches the three-dimensional model?',
