    '개인화와 맞춤화': ' Personalization and customization',
    '가상현실(VR)은 가상 환경을, 증강현실(AR)은 현실에 디지털 요소를 겹치는 방식을 뜻합니다.':
      ' Virtual reality (VR) provides a virtual environment; augmented reality (AR) overlays digital elements on reality.',
    '검색 결과가 없습니다. 다른 용어로 검색해 보세요.': ' No results found. Try another term.',
    '원본 대조 기록 ↗': ' Source comparison record ↗',
    '이해 보완 · 자체 학습 활동. 강의의 경험 차원을 적용하는 가상 사례이며 교수님 강조나 실제 시험 문제가 아닙니다.':
      ' Supplementary explanation · Self-study activity. This fictional case applies the lecture’s experience dimensions and is neither instructor emphasis nor an actual exam question.',
    상황: ' Situation',
    '온라인 스터디에서 발표 자료를 함께 수정하려고 합니다. 참여자는 수정 결과가 언제 반영되는지 모르고, 다른 사람이 무엇을 바꾸는지도 찾기 어렵다고 말합니다. 아래 순서대로 현재 경험과 목표 경험을 메모하세요.':
      ' An online study group wants to edit presentation materials together. Participants say they cannot tell when their edits take effect or easily find what others changed. Record the current and target experiences in the following order.',
    '관찰과 해석 나누기:': ' Separate observation and interpretation: ',
    '‘수정 후 반영 여부를 다시 물었다’는 관찰과 ‘내 조작이 반영됐다는 확신이 부족하다’는 해석을 두 칸에 적습니다.':
      ' In two columns, record the observation “asked again whether an edit was saved” and the interpretation “lacks confidence that an action took effect.”',
    '세 차원으로 질문하기:': ' Ask questions across three dimensions: ',
    '감각에서는 함께 작업하는 느낌과 실재감, 판단에서는 누가 변화를 일으킨다고 느끼는지와 기인점, 구성에서는 사람·자료·도구 사이 관계의 복잡도를 살펴봅니다.':
      ' For sensation, examine presence and the feeling of working together; for judgment, examine perceived causality and who initiates changes; for composition, examine relationship complexity among people, materials, and tools.',
    '목표 경험 쓰기:': ' Write the target experience: ',
    '‘좋은 UX’ 대신 ‘내 수정이 반영됐는지 알고, 동료의 변경과 구별하며 발표 자료를 완성한다’처럼 경험을 구체적으로 씁니다.':
      ' Replace “good UX” with a concrete experience such as “complete the presentation knowing my edits are saved and distinguishing them from colleagues’ changes.”',
    '설계와 확인 연결하기:': ' Connect design with verification: ',
    '변경자 이름·저장 상태·수정 내역 중 필요한 표시를 제안하고, 그 표시로 사용자가 무엇을 판단할 수 있어야 하는지 적습니다.':
      ' Propose needed indicators such as editor names, save status, or edit history, and state what users should be able to judge from them.',
    '분석 예시와 주의할 점': ' Example analysis and cautions',
    '저장 상태는 내 행동과 결과의 연결을 이해하는 데 도움을 줄 수 있다. 변경자 표시는 누가 수정했는지 판단하는 단서가 된다. 수정 내역을 작업 단위로 묶으면 관계를 따라가기 쉬워질 수 있다.':
      ' Save status may help users understand the connection between actions and results. Editor labels provide clues about who made a change. Grouping edit history by work unit may make relationships easier to follow.',
    '표시를 많이 넣는다고 항상 더 좋은 경험이 되지는 않는다. 협업 중인 사람이 많고 알림이 빈번하면 오히려 복잡해질 수 있다. ‘누가 수정했는지 설명해 보세요’라는 확인 과업으로 설계 의도를 점검한다. 이는 제안의 평가 방법이며 관찰 결과를 미리 확정한 것은 아니다.':
      ' More indicators do not always improve experience. Many collaborators and frequent notifications may increase complexity. Check the design intent with a task such as “explain who made this edit.” This is a proposed evaluation method, not a predetermined observation result.',
    '세 차원별 질문 하나, 현재 경험의 근거, 목표 경험 한 문장, 설계안과 확인 과업을 한 쌍으로 작성합니다.':
      ' Write one question for each dimension, evidence for current experience, one target-experience sentence, and a paired design proposal and verification task.',
    '챕터 이동': ' Chapter navigation',
    '← 1장 전체 강의': '← Chapter 1 full lecture',
    '3장 전체 강의 →': ' Chapter 3 full lecture →',
    '전체 챕터로 →': ' All chapters →',
    'HCI. · 2장 HCI 3.0과 사용자경험': ' HCI. · Chapter 2 HCI 3.0 and user experience',
    'HCI 3.0 · 2장 교수님 강조 요약': ' HCI 3.0 · Chapter 2 instructor-emphasis summary',
    '사용자 경험, 세 차원으로 연결하기.': ' Connect user experience through three dimensions.',
    '실재감: 세 유형, 두 조절 요인.': ' Presence: three types and two regulating factors.',
