    '“책방에 가야 한다”라고만 생각하면 온라인 구매를 놓칠 수 있습니다. 문제 표상은 무엇을 해결해야 하는지에 대한 해석이므로, 처음 떠오른 해결 수단과 목표를 구분해야 합니다.':
      ' Thinking only “I must go to a bookstore” may overlook online purchasing. Because problem representation interprets what needs solving, distinguish the goal from the first solution that comes to mind.',
    '“과제 버튼이 필요하다”는 이미 해결 수단을 포함합니다. 먼저 “학생이 기한 안에 올바른 파일을 제출하고 완료 여부를 알아야 한다”라는 목표와 제약을 정리하면, 필요한 기능을 더 정확히 판단할 수 있습니다.':
      ' “We need an assignment button” already includes a solution. First clarify the goal and constraints—students must submit the correct file before the deadline and know that submission is complete—to judge necessary functions more accurately.',
