    'rPPG · 원격 광용적맥파 측정': ' rPPG · Remote photoplethysmography',
    '내용·강조 대조 기록 ↗': ' Content and emphasis comparison record ↗',
    '이해 보완 · 자체 학습 활동. 아래는 개념을 적용하기 위한 가상 사례입니다. 실제 서비스 평가 결과가 아닙니다.':
      ' Supplementary explanation · Self-study activity. The following is a fictional case for applying concepts, not an actual service evaluation result.',
    '학생이 수업 전에 빈 강의실을 찾아 조별 모임을 열려고 합니다. 서비스는 강의실 목록과 사용 가능 시간을 보여 주지만, 건물 위치와 인원 제한은 표시하지 않습니다.':
      ' A student wants to find an empty classroom for a group meeting before class. The service shows classroom lists and available times but omits building locations and capacity limits.',
    '문제 공간:': ' Problem space: ',
    '초기 상태(모일 장소를 모름), 목표 상태(조건에 맞는 장소 확정), 가능한 행동(시간·강의실 탐색), 제약(이동 거리·인원·모임 시간)을 구분해 씁니다.':
      ' Distinguish the initial state (no meeting place known), goal state (a suitable place confirmed), available actions (searching times and rooms), and constraints (travel distance, group size, and meeting time).',
    '심성 모형:': ' Mental model: ',
    '학생이 ‘목록에 뜨면 지금 사용할 수 있다’고 기대한다면 실제 예약·이용 조건과 무엇이 다른지 적습니다. 사용자의 기대는 조사로 확인해야 할 가설입니다.':
      ' If a student expects that “a listed room can be used now,” explain how this differs from actual reservation and usage conditions. This user expectation is a hypothesis to verify through research.',
    '가치:': ' Value: ',
    '장소를 찾는 시간 절약 같은 수단적 가치와, 모임 준비에 대한 안도감 같은 경험적 가치를 각각 적습니다.':
      ' Record instrumental value, such as time saved finding a place, and experiential value, such as relief about meeting preparations.',
    '평가 조건:': ' Evaluation conditions: ',
    '장소를 찾는 데 필요한 기능이 있는지와, 실제 인원·시간·거리 조건에서 쓸 수 있는지를 나눠 점검합니다. 이 장의 유효성과 환경 적합성을 함께 적용합니다.':
      ' Separately check whether the needed room-finding functions exist and whether they work under actual group-size, time, and distance constraints. Apply efficacy and environmental suitability together.',
    '개선안과 확인 과업 예시': ' Example improvement and verification task',
    '개선안: 강의실별 수용 인원·위치·이용 조건을 제공하고 원하는 시간과 인원으로 좁혀 본다. 확인 과업: ‘수업 종료 후 10분 안에 이동할 수 있고 5명이 30분간 모일 장소를 골라 이유를 설명하세요.’':
      ' Proposal: provide each room’s capacity, location, and usage conditions, and filter by desired time and group size. Verification task: “Choose a place reachable within ten minutes after class where five people can meet for thirty minutes, and explain why.”',
    '목록을 빨리 찾았어도 실제로 사용할 수 없는 방을 골랐다면 목표 달성을 확인한 것이 아니다. 찾는 속도, 선택한 장소가 제약을 충족하는지, 선택 이유를 함께 기록한다. 화면 조작의 편리함만으로 유용성 전체를 판단하지 않는다.':
      ' Quickly finding a list does not establish goal achievement if the selected room cannot actually be used. Record search speed, whether the chosen place meets constraints, and the reasons for selection together. Do not judge overall usefulness solely from ease of screen operation.',
    '문제 공간 네 요소, 사용자 기대와 실제 조건의 차이, 두 가치, 유효성·환경 적합성 확인 항목을 각각 작성합니다.':
      ' Record the four problem-space elements, the gap between user expectations and actual conditions, both values, and checks for efficacy and environmental suitability.',
